#[test]
fn test_add() {
    let a = VolumeFlow::from_base(2.0);
    let b = VolumeFlow::from_base(3.0);
    assert!(((a + b).as_base() - 5.0).abs() < 1e-12);
}

#[test]
fn test_sub() {
    let a = VolumeFlow::from_base(5.0);
    let b = VolumeFlow::from_base(3.0);
    assert!(((a - b).as_base() - 2.0).abs() < 1e-12);
}

#[test]
fn test_neg() {
    assert!(((-VolumeFlow::from_base(4.0)).as_base() + 4.0).abs() < 1e-12);
}

#[test]
fn test_mul_num() {
    assert!(((VolumeFlow::from_base(4.0) * 2.0).as_base() - 8.0).abs() < 1e-12);
}

#[test]
fn test_div_num() {
    assert!(((VolumeFlow::from_base(6.0) / 2.0).as_base() - 3.0).abs() < 1e-12);
}

#[test]
fn test_div_same_type() {
    assert!((VolumeFlow::from_base(6.0) / VolumeFlow::from_base(2.0) - 3.0).abs() < 1e-12);
}

#[test]
fn from_str_base_unit() {
    let abbr = VolumeFlowUnit::CubicMeterPerSecond.abbreviation();
    let s = format!("1 {}", abbr);
    let parsed: VolumeFlow = s.parse().expect("parse failed");
    let expected = VolumeFlow::from_cubic_meters_per_second(1.0).as_base();
    assert!((parsed.as_base() - expected).abs() / expected.abs().max(1.0) < RT_EPS);
}
